with customer_summary as (select customer_id, concat_ws(', ', sort_array(collect_set(account_type))) as account_type_values from accounts where account_type in ('CHECKING', 'SAVINGS') group by customer_id) select customers.id, customers.credit_limit, customer_summary.account_type_values from customers left join customer_summary on customers.id = customer_summary.customer_id order by id
